/// as the primer's own "a value that touches t or f has left the slice" — the
/// information layer has no B4 representation, which is expected, not lossy
/// by accident.
fn reg16_3_to_b4(v: Reg16_3) -> B4 {
    match (v.big_t, v.big_f) {
        (false, false) => B4::N,
        (true, false)  => B4::T,
        (false, true)  => B4::F,
        (true, true)   => B4::B,
