#!/usr/bin/env python3
"""imasm_compile.py — compile a bare IMASM glyph word into a real, standalone
native ELF executable.

Takes one word (12 core marks, no ROTAT/three-way) from a .imasm file and
generates C implementing the exact tick loop gpu_kernel.rs's CUDA kernel and
kernel.rs's CPU reference both run, then compiles it with gcc into a real
binary. The compiled binary needs no interpreter, no vox, no cargo host
process at runtime -- it IS the program, running on bare silicon.

Usage: imasm_compile.py <file.imasm> <line_number 1-based> <output_path>
"""
import sys

GLYPH_TO_ID = {
    '⊢': 0,  # VINIT
    '⊣': 1,  # TANCH
    '≻': 2,  # AFWD
    '≺': 3,  # AREV
    '⋈': 4,  # CLINK
    '⊤': 5,  # EVALT
    '∈': 6,  # FSPLIT
    '∋': 7,  # FFUSE
    '⊙': 8,  # IMSCRIB
    '⊥': 9,  # EVALF
    '⊞': 10, # ENGAGR
    '⊡': 11, # IFIX
}

C_TEMPLATE = r"""
// Compiled from an IMASM glyph word. No libc: raw syscalls only.
typedef unsigned char u8;
typedef unsigned int u32;
typedef unsigned long u64;

static long sys_write(int fd, const void *buf, unsigned long n) {
    long ret;
    __asm__ volatile ("syscall" : "=a"(ret) : "a"(1), "D"(fd), "S"(buf), "d"(n) : "rcx","r11","memory");
    return ret;
}
static void sys_exit(int code) {
    __asm__ volatile ("syscall" :: "a"(60), "D"(code) : "memory");
    __builtin_unreachable();
}

static const u8 PROG[] = { %(prog)s };
#define PLEN %(plen)d
#define MAX_TICKS %(max_ticks)d

static char outbuf[4096];
static int outlen = 0;
static void putc_(char c) { outbuf[outlen++] = c; }
static void puts_(const char *s) { while (*s) putc_(*s++); }
static void putu(u64 v) {
    char tmp[24]; int n = 0;
    if (v == 0) { putc_('0'); return; }
    while (v > 0) { tmp[n++] = '0' + (v % 10); v /= 10; }
    while (n > 0) putc_(tmp[--n]);
}
static const char *valname(u8 v) {
    switch (v & 3) { case 1: return "T"; case 2: return "F"; case 3: return "B"; default: return "N"; }
}

void _start(void) {
    u8 stack[256]; int top = 0;
    u8 reg[8]; for (int i = 0; i < 8; i++) reg[i] = 0;
    u8 engagr = 0;
    u8 mem[4]; mem[0] = mem[1] = mem[2] = mem[3] = 0;
    u32 fresume[64]; u8 fright[64]; u8 fset[64];
    int fdepth = 0;
    u32 ip = 0;
    u64 tick = 0;
    u8 halted = 0;
    u32 plen = PLEN;
    u8 P[64];
    for (u32 i = 0; i < plen; i++) P[i] = PROG[i];

    while (!halted && tick < MAX_TICKS && plen > 0) {
        tick++;
        if (ip >= plen) { ip = 0; if (top > 200) P[ip] = 1; }
        u8 tok = P[ip];
        u32 next_ip = ip + 1;
        if (next_ip >= plen) next_ip = 0;

        if (tok == 0) {
            if (top < 256) stack[top++] = 0;
        } else if (tok == 1) {
            u8 v = (top > 0) ? stack[--top] : 0;
            mem[reg[0] & 3] = v;
            if (fdepth == 0) { halted = 1; break; }
        } else if (tok == 2) {
            reg[0] = (reg[0] + 1) & 3;
        } else if (tok == 3) {
            u8 v = (top > 0) ? stack[--top] : 0;
            u8 nb = ((v & 1) << 1) | ((v & 2) >> 1);
            if (top < 256) stack[top++] = nb;
            reg[0] = (reg[0] - 1) & 3;
        } else if (tok == 4) {
            reg[3] = reg[1] & reg[2];
        } else if (tok == 5) {
            u8 v = (top > 0) ? stack[--top] : 0;
            if (top < 256) stack[top++] = (v == 1) ? 1 : 0;
        } else if (tok == 6) {
            u8 v = (top > 0) ? stack[top - 1] : 0;
            u32 ff = plen, depth = 1;
            u32 i = (ip + 1) % plen, start = i;
            do {
                if (P[i] == 6) depth++;
                else if (P[i] == 7) { depth--; if (depth == 0) { ff = i; break; } }
                i = (i + 1) % plen;
            } while (i != start);
            u32 resume = (ff + 1 >= plen) ? 0 : ff + 1;
            if (fdepth < 64) { fresume[fdepth] = resume; fright[fdepth] = 0; fset[fdepth] = 0; fdepth++; }
            if (fdepth > 0) { fright[fdepth - 1] = v; fset[fdepth - 1] = 1; }
            if (top < 256) stack[top++] = v;
        } else if (tok == 7) {
            u8 left = (top > 0) ? stack[--top] : 0;
            if (fdepth > 0) {
                fdepth--;
                u8 right = fset[fdepth] ? fright[fdepth] : 0;
                if (top < 256) stack[top++] = left | (right & 3);
                next_ip = fresume[fdepth];
            } else {
                if (top < 256) stack[top++] = left;
            }
        } else if (tok == 8) {
            int diversity = 0;
            { u8 seen[16]; for (int i = 0; i < 16; i++) seen[i] = 0;
              for (u32 i = 0; i < plen; i++) { u8 t = P[i]; if (t < 16 && !seen[t]) { seen[t] = 1; diversity++; } } }
            u8 self_ref = (plen > 0 && P[0] == P[plen - 1]) ? 1 : 0;
            u8 frob_pos = 0;
            for (u32 i = 0; i < plen; i++) { u8 t = P[i]; if (t == 6 || t == 7 || t == 12 || t == 13) { frob_pos = 1; break; } }
            u8 dial = 0;
            { u8 h5 = 0, h9 = 0, h10 = 0;
              for (u32 i = 0; i < plen; i++) { if (P[i] == 5) h5 = 1; else if (P[i] == 9) h9 = 1; else if (P[i] == 10) h10 = 1; }
              if (h5 && h9 && h10) dial = 1; }
            reg[4] = (u8)(diversity & 3);
            reg[5] = self_ref ? 1 : 2;
            reg[6] = frob_pos ? 1 : 2;
            reg[7] = dial ? 1 : 2;
        } else if (tok == 9) {
            u8 v = (top > 0) ? stack[--top] : 0;
            if (top < 256) stack[top++] = (v == 2) ? 2 : 0;
        } else if (tok == 10) {
            engagr = 1;
            if (top < 256) stack[top++] = 3;
        } else if (tok == 11) {
            u8 v = (top > 0) ? stack[--top] : 0;
            mem[reg[0] & 3] = v;
        }

        ip = next_ip;
        if (ip >= plen) { ip = 0; if (top > 200) P[ip] = 1; }
    }

    puts_("halted: "); puts_(halted ? "true" : "false");
    puts_("   ticks: "); putu(tick); putc_('\n');
    puts_("stack (bottom..top): [");
    for (int i = 0; i < top; i++) { if (i) putc_(' '); puts_(valname(stack[i])); }
    puts_("]  depth "); putu((u64)top); putc_('\n');
    puts_("registers: [");
    for (int i = 0; i < 8; i++) { if (i) putc_(' '); puts_(valname(reg[i])); }
    puts_("]  engagr "); puts_(engagr ? "true" : "false"); putc_('\n');
    puts_("memory[0..4]: [");
    for (int i = 0; i < 4; i++) { if (i) putc_(' '); puts_(valname(mem[i])); }
    puts_("]\n");

    sys_write(1, outbuf, (unsigned long)outlen);
    sys_exit(halted ? 0 : 1);
}
"""


def main():
    if len(sys.argv) != 4:
        print(__doc__)
        sys.exit(1)
    imasm_file, lineno, out_path = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    with open(imasm_file, encoding="utf-8") as f:
        lines = [l.rstrip("\n") for l in f if l.strip()]
    word = lines[lineno - 1]
    ids = []
    for c in word:
        if c not in GLYPH_TO_ID:
            print(f"not a compilable mark: {c!r} (only the 12 core marks, no ROTAT/three-way)")
            sys.exit(1)
        ids.append(GLYPH_TO_ID[c])

    prog_c = ", ".join(str(i) for i in ids)
    c_src = C_TEMPLATE % {"prog": prog_c, "plen": len(ids), "max_ticks": 65536}

    c_path = out_path + ".c"
    with open(c_path, "w") as f:
        f.write(c_src)

    import subprocess
    r = subprocess.run(
        ["gcc", "-O2", "-nostdlib", "-static", "-fno-stack-protector",
         "-Wl,-e,_start", "-o", out_path, c_path],
        capture_output=True, text=True,
    )
    if r.returncode != 0:
        print("gcc failed:\n" + r.stderr)
        sys.exit(1)
    print(f"compiled {imasm_file}:{lineno} ({len(ids)} marks) -> {out_path}")


if __name__ == "__main__":
    main()

